-- 2026-10-17 (аудиты Codex №2/№3). Forward-safe для окружений, где 0024 уже применена.
-- 1) Флаг «вектор версии устарел». Ожидающие запросы 0024 переносятся во флаг текущей applied-версии
--    (диспетчер worker подбирает applied+embedding_stale). Пользователь без applied-версии (идёт пересборка):
--    новая версия считает свои векторы сама; строка 0024 сохраняется (таблица не удаляется — отдельная cleanup-миграция).
ALTER TABLE "capability_profiles" ADD COLUMN "embedding_stale" boolean DEFAULT false NOT NULL;--> statement-breakpoint
UPDATE "capability_profiles" cp SET "embedding_stale" = true
  WHERE cp."status" = 'applied'
    AND EXISTS (SELECT 1 FROM "profile_embedding_refresh_requests" r WHERE r."user_id" = cp."user_id");--> statement-breakpoint
-- 2) Полный детерминированный порядок журнала: существующие строки — по (decided_at, id), новые — identity.
ALTER TABLE "profile_item_decisions" ADD COLUMN "seq" bigint;--> statement-breakpoint
UPDATE "profile_item_decisions" d SET "seq" = o.rn
  FROM (SELECT "id", row_number() OVER (ORDER BY "decided_at", "id") AS rn FROM "profile_item_decisions") o
  WHERE d."id" = o."id";--> statement-breakpoint
ALTER TABLE "profile_item_decisions" ALTER COLUMN "seq" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "profile_item_decisions" ALTER COLUMN "seq" ADD GENERATED BY DEFAULT AS IDENTITY (sequence name "profile_item_decisions_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1);--> statement-breakpoint
SELECT setval(pg_get_serial_sequence('"profile_item_decisions"', 'seq'), COALESCE((SELECT max("seq") FROM "profile_item_decisions"), 0) + 1, false);--> statement-breakpoint
CREATE INDEX "capability_profiles_embedding_stale_idx" ON "capability_profiles" USING btree ("user_id") WHERE embedding_stale;
